/bin/bash -lc "python - <<'PY'
from sim import Sim
import numpy as np
sim=Sim();
target=np.array([0,-0.5,0,-2.0,0,2.0,0])
sim.data.ctrl[:7]=target
for k in [1,10,50,200,500]:
    while sim._step_counter<k: sim.step(1)
    print('step',k,'qpos',np.round(sim.data.qpos[:7],3),'err',np.round(target-sim.data.qpos[:7],3))
PY"

